mapper.select:
SELECT 
FROM api_project
WHERE supplier_id = #{supplierId}
  AND supplier_project_id = #{supplierProjectId}

mapper.update:
UPDATE api_project
SET earliest_session_start_time = (
        SELECT MIN(session_start_time) FROM api_session WHERE project_id = #{projectId}
    ),
    latest_session_start_time = (
        SELECT MAX(session_start_time) FROM api_session WHERE project_id = #{projectId}
    ),
    update_time = now()
WHERE id = #{projectId}

mapper.select:
SELECT id
FROM api_project
WHERE supplier_id = #{supplierId}
  AND sale_status = #{saleStatus}
  AND MOD(id, #{shardTotal}) = #{shardIndex}
